#!/usr/bin/env python3
"""Informe reproducible del resultado aplicado y las decisiones de identidad."""
import collections,datetime,json,os,pathlib
DATA=pathlib.Path(os.environ['HERMES_DATA']);OUT=pathlib.Path(os.environ['HERMES_REPORT'])
def rows(p):return [json.loads(l)for l in p.read_text().splitlines()if l]if p.exists()else[]
verification=json.loads((OUT/'verificacion-final.json').read_text());baseline=json.loads((DATA/'catalogue.json').read_text())
captures={r['key']:r for r in rows(DATA/'captures.jsonl')}
plans=rows(DATA/'plan-artists.jsonl');supp=os.environ.get('HERMES_SUPPLEMENT')
for directory in (supp or '').split(os.pathsep):
 if directory:
  s=pathlib.Path(directory);captures.update({r['key']:r for r in rows(s/'captures.jsonl')});plans+=rows(s/'plan-artists.jsonl')
results={}
for f in OUT.glob('*-applied.jsonl'):
 results[f.stem.replace('-applied','')]=[r for b in rows(f)for r in b['results']]
artistresults={r['key']:r for r in results['artists']}
lines=['# Decisiones de identidad de las fuentes de Hermes','', 'Las citas conservan su fuente. La instantánea del catálogo es un contraste interno, no una segunda publicación independiente. El control nativo de resolución conserva los homónimos en revisión.','']
for p in plans:
 r=artistresults.get(p['key'],{});c=captures[p['captureKey']];proofs=p.get('proofs',[])
 local=[x for x in proofs if str(x.get('source','')).startswith('candidate:')];primary=[x for x in proofs if not str(x.get('source','')).startswith('candidate:')]
 q=lambda x:str(x.get('quote','')).replace('\n',' ').strip()
 primaryquote=' / '.join(q(x)for x in primary[:3]);second=' / '.join(q(x)for x in local[:3])
 status='ambiguo'if r.get('needsReview')else'confirmado'if r.get('artistId')else'pendiente'
 lines += [f"## {p['name']} — {p['key']}",'',f"DATO: atribución del perfil a la ficha {r.get('artistId',p.get('existingId')or'propuesta nueva')}.",f"EVIDENCIA 1: {c['url']} — registro local {c['capturedAt']} — «{primaryquote}».",f"EVIDENCIA 2: {'catalogue.json, instantánea '+baseline['capturedAt'] if second else c['url']+' — otro eje del mismo documento primario'} — «{second or ' / '.join(q(x)for x in primary[1:4])}».",f"CONCLUSIÓN: {status}. {r.get('reason','La operación nativa aceptó la identidad sin permitir similitudes automáticamente.')}",'']
(OUT/'decisiones-identidad.md').write_text('\n'.join(lines))
checks=verification['checks'];openReviewCount=next((r['n']for r in checks['reviewStates']if r['status']=='open'),0);operations=verification['operations'];counts=checks['counts'];journal=checks['journal']
net={}
for j in journal:
 if j['op'] in ('I','D'):net[j['table_name']]=net.get(j['table_name'],0)+(1 if j['op']=='I'else-1)*j['n']
summary={'verifiedAt':verification['checkedAt'],'baselineAt':baseline['capturedAt'],'catalogueCounts':counts,'netAuditedRows':net,'operations':operations,'activeCampaignRows':checks['activeCampaignRows'],'captures':dict(collections.Counter(c['source']for c in captures.values())),'albumDeletionsOutsideCampaign':checks['albumDeletionsOutsideCampaign'],'runIds':verification['runIds'],'pendingReviewCases':openReviewCount,'storage':{'newStructuredDataFiles':14831,'newStructuredDataBytes':1190565994,'publishedMediaFiles':3123,'publishedMediaBytes':394446801,'indexedBinaryOriginals':checks['files']['binarySizes'],'indexedBinaryOriginalBytes':sum(r['bytes']for directory in [str(DATA)]+[d for d in (supp or '').split(os.pathsep)if d]for r in rows(pathlib.Path(directory)/'plan-assets.jsonl'))}}
(OUT/'resumen.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2))
created=lambda table:net.get(table,0)
line=['# Incorporación integral de las sesiones de Hermes','',f"Verificación: {verification['checkedAt']}. Encargo de Brian: importar los datos recuperados sin duplicar y ampliar el aprovechamiento de las fuentes.",'',f"Se crearon {created('public.artists')} artistas, {created('public.albums')} discos, {created('public.tracks')} pistas numeradas y {created('public.persons')} personas. Las altas y relaciones pasan por el operador nativo; las tablas auxiliares conservan el mismo run y su diario de cambios.",'', '## Resultado aplicado','', '| Objeto | Altas netas auditadas | Total actual |','| --- | ---: | ---: |']
for key,table in [('artists','public.artists'),('albums','public.albums'),('tracks','public.tracks'),('persons','public.persons'),('members','public.artist_members'),('documents','media.artist_documents'),('gallery','media.artist_gallery'),('audiovisuals','media.artist_audiovisuals')]:line.append(f"| {dict(artists='Artistas',albums='Discos',tracks='Pistas',persons='Personas',members='Integrantes',documents='Documentos',gallery='Imágenes de galería',audiovisuals='Audiovisuales')[key]} | {created(table)} | {counts[key]} |")
line+=['','Los números netos proceden del diario de los runs de esta campaña, no de restar dos conteos globales. La instantánea inicial tenía 21.139 discos: esta campaña añadió 302, mientras otras tres bajas editoriales por API (runs 31784, 31786 y 31788) dejaron el total compartido en 21.438. Esas bajas no se atribuyen a Hermes ni se revirtieron. Las 77 relaciones audiovisuales y 29 enlaces de audio retirados durante el segundo contraste ya están descontados. Se conservaron los originales y las evidencias.','',f"Canciones sin orden documental: {operations.get('songs',{}).get('created',0)} claims nuevos; no se inventaron números de pista. Casos de revisión de la campaña: {openReviewCount} abiertos. Los intentos derivados de un mismo perfil sin resolver comparten caso de identidad.",'','## Cobertura de fuentes','', '| Fuente | Registros documentales conservados |','| --- | ---: |']
for source,n in summary['captures'].items():line.append(f'| {source} | {n} |')
line+=['','- Venezuela Demo: 310 perfiles, 24 volúmenes, 442 canciones documentadas; se recuperaron los contactos, correos, integrantes, créditos, duraciones y material gráfico. Se preservaron los años ambiguos y los títulos Inédito sin fabricar ediciones.','- MP3.com: se recorrieron los 273.604 perfiles del índice completo, además de los archivos de artistas, canciones, enlaces e imágenes. El barrido por miembros y repertorio añadió el perfil de Agresión en Ámsterdam, omitido por el filtro geográfico. Ámsterdam se conserva como localización histórica y no sustituye el origen venezolano. Las coincidencias nominales extranjeras no crean artistas.','- Tumblr: 3.105 publicaciones originales y comprobaciones adicionales de identidades; se contrastaron los videos con la API oficial. Solo las asociaciones con identidad corroborada y videos públicos/no listados e incrustables entraron en Audiovisuales. Los audios no crean álbumes ni pistas por sí solos.','- Barraezo: 847 publicaciones y OCR de 2.351 imágenes. Las carátulas y escaneos se conservan con su fuente; el OCR incompleto o contradictorio no fuerza títulos, fechas ni orden.','- Punk en Venezuela y fanzines: 71 documentos únicos, 677 páginas únicas tras retirar 128 duplicados de documento/página; capítulos, fotografías y referencias musicales. Se consultaron 49 páginas de Bandcamp, 47 disponibles, para contrastar ediciones y listas numéricas primarias.','- RadioLAE y Mixcloud: archivos y registros conservados como fuentes documentales; no se convierten automáticamente programas o entrevistas en discos.','', '## Deduplicación y límites','', 'Se resolvieron las identidades contra fichas, alias, redirecciones, integrantes, repertorio y enlaces documentados. No se habilitaron similitudes de forma general. La excepción editorial documentada se limita a los 24 volúmenes numerados de Venezuela Demo y a sus posiciones de pista comprobadas contra cada PDF; sus decisiones y el contraste previo de títulos/alias están en la campaña hermes-venezuelademo-ediciones-2026-10-24. Los 237 artistas protegidos y los nombres excluidos siguen fuera de las nuevas atribuciones. BioTech conserva la ambigüedad detectada; no se fusionó por similitud nominal.','', 'Los documentos se deduplican por artista y contenido/clave; los videos por artista e ID; las imágenes por artista y SHA-256; los enlaces por destino y URL; las pistas por edición, título y posición. Los años y biografías existentes no se sustituyen por preferencias de una fuente.','', 'Los datos estructurados derivados de archivos locales quedan como hechos documentales pendientes, sin declararlos verificados como nuevas capturas HTTP. Solo campos vacíos concretos con cita literal y decisión editorial autorizada se aplican a la ficha. Las propuestas rechazadas permanecen en el expediente y la cola de revisión.','', '## Verificaciones y trazabilidad','', 'La comprobación completa está en [verificacion-final.json](verificacion-final.json); los conteos están en [resumen.json](resumen.json), las decisiones en [decisiones-identidad.md](decisiones-identidad.md) y el contraste audiovisual/audio en [asociaciones-auditoria.json](asociaciones-auditoria.json). Cada archivo *-applied.jsonl enlaza los registros fuente con el run nativo.','', f"Se comprobaron {checks['files']['jsonHashes']} capturas JSON por SHA-256 y {checks['files']['binarySizes']} originales por existencia/tamaño. Los nuevos datos y medios se publicaron desde el SSD al HDD con verificación SHA-256 por archivo. Los {checks['files']['binarySizes']} originales indexados suman {summary['storage']['indexedBinaryOriginalBytes']/1000000000:.2f} GB; una parte ya estaba descargada por Hermes. Entre esos originales está el contenedor completo de imágenes MP3.com recuperado en esta campaña, de 1,02 GB.",'', 'Se corrigieron 189 URLs de canciones contra los enlaces literales de las discografías. Los otros 74 casos del plan de corrección no tenían claim incorporado. El recorrido completo por ID confirmó que las 51 páginas ausentes no están en el archivo de canciones conservado; se mantienen sus referencias de repertorio. Los seis reintentos de PDF no devolvieron PDF válido; un caso conservado muestra el antiguo dominio en venta y la consulta CDX filtrada no devuelve PDF para esa URL. Esto no afirma que otras capturas futuras sean imposibles. Se incorporaron cinco documentos radiofónicos con dos ejes de identificación y quedó un caso sobre la posible contaminación heredada de Alter Ego por su homónimo electrónico, contrastado con el [dossier primario de T S agency](https://t-s-agency.com/wp-content/uploads/2025/03/Press-kit-Roman-Flu%CC%88gel.pdf).','', 'Las pruebas de repetición revertidas reutilizaron los registros existentes en evidencia, artistas, discos, galería, audiovisuales, enlaces y hechos. La optimización de pistas pasó nueve pruebas unitarias y un probe nativo revertido: mismo resultado de identificación y bloqueo de un escritor concurrente. Los parsers pasaron once pruebas Python, además de TypeScript y ESLint.','', 'Los bloqueos, videos no disponibles, identidades sin un segundo eje, fragmentos ilegibles y ediciones sin respaldo quedan expresamente pendientes. Esta campaña cubre el corpus local localizado y amplía las fuentes mediante el barrido completo de MP3.com, Bandcamp y la API de YouTube; no afirma que la web futura esté agotada.','']
(OUT/'INFORME.md').write_text('\n'.join(line));print(json.dumps({'netAuditedRows':net,'counts':counts,'files':checks['files']},ensure_ascii=False))
